<div class="page-head"><div><span class="eyebrow">Data Quality</span><h1>Upload Monitoring</h1><p>Review report batches across every business.</p></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Business</th><th>Period</th><th>Frequency</th><th>Completeness</th><th>Status</th><th>Uploaded by</th><th></th></tr></thead><tbody><?php foreach($batches as $b):?><tr><td><?=e($b['business_name'])?></td><td><?=e(reporting_us_date($b['period_start']))?> – <?=e(reporting_us_date($b['period_end']))?></td><td><?=e(ucfirst($b['frequency']))?></td><td><?=numfmt($b['completeness_score'])?>%</td><td><span class="status status-<?=e($b['status'])?>"><?=e(ucfirst($b['status']))?></span><?php if($b['warning_count']):?><small class="block"><?=$b['warning_count']?> warning(s)</small><?php endif;?></td><td><?=e($b['uploaded_by_name'])?></td><td><?php if($b['status']==='completed'):?><form method="post" action="<?=url('admin-business-view')?>" class="inline-action-form"><?=csrf_field()?><input type="hidden" name="business_id" value="<?=e($b['business_id'])?>"><input type="hidden" name="destination" value="report"><input type="hidden" name="resource_id" value="<?=e($b['id'])?>"><button class="link-button" type="submit">View Report</button></form><?php else:?><span title="<?=e($b['error_message'])?>">Details</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
